import * as zod from "zod";
import { OrderStatus } from "../types";

/**
 * Schema for creating a new order
 *
 * Order IDs and timestamps are generated by the backend.
 * Payment completion/refund fields are also excluded because
 * they should be controlled by the payment/order lifecycle.
 */
export const createOrderSchema = zod.object({
  userId: zod.string().min(1, "User ID is required"),

  resourceId: zod.string().min(1, "Resource ID is required"),

  creatorId: zod.string().min(1, "Creator ID is required"),

  title: zod.string().min(1, "Order title is required"),

  amount: zod.coerce.number().nonnegative("Amount cannot be negative"),

  currency: zod.string().min(1, "Currency is required").default("INR"),

  status: zod.nativeEnum(OrderStatus).default(OrderStatus.pending),

  paymentId: zod.string().optional().or(zod.literal("")),

  paymentMethod: zod.string().optional().or(zod.literal("")),
});

/**
 * Schema for updating an existing order
 *
 * Immutable identity fields are excluded because an existing order
 * should not be moved to another user/resource/creator.
 */
export const updateOrderSchema = zod.object({
  title: zod.string().min(1, "Order title is required").optional(),

  amount: zod.coerce
    .number()
    .nonnegative("Amount cannot be negative")
    .optional(),

  currency: zod.string().min(1, "Currency is required").optional(),

  status: zod.nativeEnum(OrderStatus).optional(),

  paymentId: zod.string().optional().or(zod.literal("")),

  paymentMethod: zod.string().optional().or(zod.literal("")),
});

/**
 * Schema for order filters
 */
export const orderFiltersSchema = zod.object({
  search: zod.string().optional(),

  userId: zod.string().optional(),

  resourceId: zod.string().optional(),

  creatorId: zod.string().optional(),

  status: zod.nativeEnum(OrderStatus).optional(),

  paymentMethod: zod.string().optional(),

  currency: zod.string().optional(),

  minAmount: zod.coerce
    .number()
    .nonnegative("Minimum amount cannot be negative")
    .optional(),

  maxAmount: zod.coerce
    .number()
    .nonnegative("Maximum amount cannot be negative")
    .optional(),

  createdAfter: zod.union([zod.string(), zod.date()]).optional(),

  createdBefore: zod.union([zod.string(), zod.date()]).optional(),

  sortBy: zod.enum(["createdAt", "updatedAt", "amount", "title"]).optional(),

  sortOrder: zod.enum(["asc", "desc"]).optional(),

  page: zod.coerce.number().int().positive().optional(),

  limit: zod.coerce.number().int().positive().optional(),
});

/**
 * Schema for changing order status
 */
export const updateOrderStatusSchema = zod.object({
  status: zod.nativeEnum(OrderStatus),
});

/**
 * Schema for completing an order
 */
export const completeOrderSchema = zod.object({
  paymentId: zod.string().optional().or(zod.literal("")),

  paymentMethod: zod.string().optional().or(zod.literal("")),
});

/**
 * Schema for refunding an order
 */
export const refundOrderSchema = zod.object({
  reason: zod
    .string()
    .max(500, "Refund reason cannot exceed 500 characters")
    .optional(),
});

/**
 * Type exports
 */
export type CreateOrderFormValues = zod.infer<typeof createOrderSchema>;

export type UpdateOrderFormValues = zod.infer<typeof updateOrderSchema>;

export type OrderFiltersFormValues = zod.infer<typeof orderFiltersSchema>;

export type UpdateOrderStatusFormValues = zod.infer<
  typeof updateOrderStatusSchema
>;

export type CompleteOrderFormValues = zod.infer<typeof completeOrderSchema>;

export type RefundOrderFormValues = zod.infer<typeof refundOrderSchema>;
